const traitLabels={alpha:'Скорость обучения',forgetting:'Забывание',trace:'След',discount:'Дисконтирование',memoryAge:'Давность',shortCapacity:'Краткая память',longCapacity:'Долгая память',consolidationThreshold:'Порог закрепления',longRetention:'Длительность закрепления'};
export function numericRuleRows(){
 const rows=[];for(const g of NUMERIC_RULE_GROUPS)for(const [key,value] of Object.entries(g.values))if(typeof value==='number'){
  const field=g.fields[key];if(!field)throw new Error(`Не описан параметр ${g.id}.${key}`);
  const [label,unit]=Array.isArray(field)?field:[field,g.unit];rows.push({group:g.id,key,name:['clock','prices','layout'].includes(g.id)?key:`${g.symbol}.${key}`,label,unit,value,file:g.file});
 }
 for(const [key,rule] of Object.entries(COGNITIVE_SCALE_RULES))for(const [part,value] of Object.entries(rule))rows.push({group:'trait-scales',key:key+'.'+part,name:`COGNITIVE_SCALE_RULES.${key}.${part}`,label:traitLabels[key]+(part==='offset'?': нижняя граница':': размах добавки'),unit:['memoryAge','longRetention'].includes(key)?'Т':key.includes('Capacity')?'записи':'коэффициент',value,file:'cognition-rules.js'});
 return rows;
}
